import { API_BASE_URL } from '../config/api';

export interface DeleteAccountResult {
  deleted: boolean;
}

export async function deleteAccount(): Promise<DeleteAccountResult> {
  const response = await fetch(`${API_BASE_URL}/account`, { method: 'DELETE' });
  if (!response.ok) {
    throw new Error(`Failed to delete account (status ${response.status})`);
  }
  return { deleted: true };
}

import { useState, useCallback } from 'react';
import { View, Text, Pressable, StyleSheet, ActivityIndicator } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { deleteAccount } from '../services/account';

const colors = {
  background: '#FFFFFF',
  text: '#1A1A1A',
  danger: '#DC2626',
  dangerText: '#FFFFFF',
  muted: '#6B7280',
};

export function AccountDeleteScreen(): JSX.Element {
  const [confirming, setConfirming] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [deleted, setDeleted] = useState(false);

  const handleDelete = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      await deleteAccount();
      setDeleted(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Deletion failed');
    } finally {
      setLoading(false);
    }
  }, []);

  if (deleted) {
    return (
      <SafeAreaView style={styles.safe}>
        <Text style={styles.confirmation}>Your account has been deleted.</Text>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={styles.safe}>
      <View style={styles.container}>
        <Text style={styles.title}>Delete account</Text>
        <Text style={styles.body}>This permanently removes your account and data. This cannot be undone.</Text>
        {error ? <Text style={styles.error}>{error}</Text> : null}
        {confirming ? (
          <View style={styles.row}>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel="Confirm account deletion"
              style={styles.confirmButton}
              onPress={handleDelete}
              disabled={loading}
            >
              {loading ? <ActivityIndicator color={colors.dangerText} /> : <Text style={styles.confirmText}>Yes, delete</Text>}
            </Pressable>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel="Cancel account deletion"
              style={styles.cancelButton}
              onPress={() => setConfirming(false)}
              disabled={loading}
            >
              <Text style={styles.cancelText}>Cancel</Text>
            </Pressable>
          </View>
        ) : (
          <Pressable
            accessibilityRole="button"
            accessibilityLabel="Start account deletion"
            style={styles.confirmButton}
            onPress={() => setConfirming(true)}
          >
            <Text style={styles.confirmText}>Delete account</Text>
          </Pressable>
        )}
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.background },
  container: { flex: 1, justifyContent: 'center', padding: 24 },
  title: { fontSize: 24, fontWeight: 'bold', marginBottom: 12, color: colors.text },
  body: { fontSize: 15, lineHeight: 22, color: colors.muted, marginBottom: 24 },
  error: { color: colors.danger, marginBottom: 12 },
  row: { flexDirection: 'row', gap: 12 },
  confirmButton: { backgroundColor: colors.danger, padding: 16, borderRadius: 8, alignItems: 'center', flex: 1 },
  confirmText: { color: colors.dangerText, fontWeight: '600' },
  cancelButton: { padding: 16, borderRadius: 8, alignItems: 'center', borderWidth: 1, borderColor: colors.danger, flex: 1 },
  cancelText: { color: colors.danger, fontWeight: '600' },
  confirmation: { color: colors.text, textAlign: 'center', marginTop: 48, fontSize: 16 },
});
